import random

import pytest


def make_ids(n: int, seed: int) -> list[int]:
    """Return n distinct non-negative record ids, determined only by seed.

    Calling make_ids with the same (n, seed) always returns the same list,
    in the same order. The function uses no ambient state: it does not read
    or modify the global random generator, the clock, the environment, or
    the filesystem.

    Raises ValueError if n is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    rng = random.Random(seed)
    return rng.sample(range(2**62), n)


def test_length() -> None:
    for n in (0, 1, 2, 10, 1000):
        assert len(make_ids(n, 7)) == n


def test_empty() -> None:
    assert make_ids(0, 123) == []


def test_distinct() -> None:
    ids = make_ids(10_000, 42)
    assert len(set(ids)) == len(ids)


def test_all_ints_non_negative() -> None:
    ids = make_ids(500, 5)
    assert all(type(i) is int for i in ids)
    assert all(i >= 0 for i in ids)


def test_same_seed_same_result() -> None:
    assert make_ids(100, 99) == make_ids(100, 99)


def test_repeated_calls_stable_order() -> None:
    first = make_ids(50, 1)
    for _ in range(3):
        assert make_ids(50, 1) == first


def test_different_seeds_differ() -> None:
    assert make_ids(50, 1) != make_ids(50, 2)


def test_negative_and_zero_seeds() -> None:
    for seed in (0, -1, -(2**40), 2**80):
        ids = make_ids(100, seed)
        assert len(set(ids)) == 100
        assert ids == make_ids(100, seed)


def test_negative_n_raises() -> None:
    with pytest.raises(ValueError):
        make_ids(-1, 0)


def test_does_not_touch_global_random_state() -> None:
    random.seed(2024)
    expected = random.random()
    random.seed(2024)
    make_ids(100, 3)
    assert random.random() == expected


def test_independent_of_global_random_state() -> None:
    random.seed(1)
    a = make_ids(100, 8)
    random.seed(2)
    b = make_ids(100, 8)
    assert a == b


def test_returns_fresh_list() -> None:
    a = make_ids(5, 4)
    a.append(-1)
    assert make_ids(5, 4) == a[:-1]

